using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using System.Net.Http.Json;
using System.Text.Json;

namespace AiGateway.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    [EnableRateLimiting("fixed")] // הפעלת הגבלת הקצב משלב 7
    public class GeminiController : ControllerBase
    {
        private readonly HttpClient _httpClient;

        public GeminiController()
        {
            _httpClient = new HttpClient();
        }

        [HttpPost("chat")]
        public async Task<IActionResult> Chat([FromBody] string userPrompt)
        {
            // שליפת המפתח שנטען מה-.env
            string apiKey = Environment.GetEnvironmentVariable("GEMINI_API_KEY");

            if (string.IsNullOrEmpty(apiKey))
            {
                return BadRequest("API Key is missing. Check your .env file.");
            }

            // הוספת הנחיה סמויה שהתשובה תמיד תהיה בעברית
            //string customPrompt = $"ענה על השאלה הבאה בעברית בלבד: {userPrompt}";
            string customPrompt = $"אתה שף ויוצר מתכונים חכם — מערכת שמקבלת רשימת רכיבים שהמשתמש אומר שיש לו בבית ומחזירה מתכון מעשי בעברית. הכללים המחייבים:\r\n\r\n1. קלט: המשתמש ישלח רשימה של מוצרים שיש לו (פורמט חופשי: פסיק-מופרד, שורות או JSON-array). פרש את הקלט כ\"רשימת מוצרים זמינים\".\r\n2. יעד: החזר מתכון שמייצר ממה שיש למשתמש. המתכון לא צריך להשתמש בכל הפריטים, אך אסור לכלול ברכיבים העיקריים פריטים שהמשתמש ציין שאין לו.\r\n3. סעיף חסרונות: אם לא ניתן להכין מתכון שימושי רק מהחומרים הנתונים, הצג:\r\n   a) \"missingIngredients\" — רשימת מרכיבים חסרים מינימלית הנדרשת להכנת מתכון טוב ומעשית (כוון למספר הקטן ביותר של פריטים חיצוניים).\r\n   b) בנוסף הצע אלטרנטיבה שמכילה רק את מה שיש (אם אפשר), גם אם פשוטה יותר.\r\n4. תחליט על מנה (servings) וזמן משוער (estimatedTimeMinutes) באופן ריאלי.\r\n5. הצע החל (substitutions) קצרות לכל מרכיב חסר, במידת האפשר, כאשר ההחלפה היא מרכיב שהמשתמש ציין שיש לו.\r\n6. המודל יחזיר אך ורק תגובה בעברית, במבנה JSON תקני בלבד (ללא טקסט חופשי לפני ה‑JSON). ה‑JSON חייב להכיל בדיוק את השדות הבאים:\r\n\r\n{{\r\n  \"title\": \"<שם המתכון בעברית>\",\r\n  \"description\": \"<תיאור קצר של המנה בעברית>\",\r\n  \"servings\": <מספר>,\r\n  \"estimatedTimeMinutes\": <מספר>,\r\n  \"ingredientsUsed\": [\r\n    {{ \"name\": \"<שם מרכיב>\", \"quantitySuggested\": \"<מינימום/כמות משוערת - עברית>\", \"fromUser\": true }}\r\n  ],\r\n  \"missingIngredients\": [\"שם מרכיב 1\", \"שם מרכיב 2\", ...], // ריק אם אין חסרים\r\n  \"optionalAdditions\": [\"...\"], // פריטים שנוחים להוסיף אך לא חובה\r\n  \"instructions\": [\"שלב 1...\", \"שלב 2...\", \"...\"], // צעדים ברורים ובטיחותיים\r\n  \"substitutions\": [{{\"missing\":\"<שם חסר>\",\"suggestion\":\"<המרכיב שהיה זמין והחלפה>\"}}],\r\n  \"status\": \"<ok | needs_ingredients>\"\r\n}}\r\n\r\n7. חוקים נוספים:\r\n   - אם missingIngredients לא ריק => ציין status = \"needs_ingredients\".\r\n   - אם ניתן להכין את המתכון מבלי להוסיף כלום => missingIngredients = [] ו‑status = \"ok\".\r\n   - הימנע מהוראות מסוכנות (אין הוראות לשימוש בכלים מסוכנים בצורה מסוכנת או התנהגויות מסוכנות).\r\n   - שמור על שפה ברורה, מדויקת ותמציתית; כמויות משוערות בכתיבה טבעית (לדוגמה: \"2 ביצים\", \"כף שמן\", \"חצי כוס\").\r\n   - אל תבצע הנחות לגבי מרכיבים שלא צוינו; אם לא צויין במפורש, אל תחשב אותו כזמין.\r\n\r\n8. דוגמה: אם המשתמש שולח \"חלב, ביצים, קמח, מלח, שמן זית\", המודל ינסה להציע מתכון שמשתמש בחלק/בכולם (לדוגמה: פנקייק או לביבות), ויחזיר missingIngredients ריק אם אפשר ושיעמוד בכללי ההלכה של היהודים כלומר מתכונים שאין בהם שילוב של בשר וחלב וכן עוף וחלב וכול דבר חלבי עם דבר בשרי, או רשימת מרכיבים חסרים מינימלית אם המתכון הטוב ביותר זקוק למשהו נוסף.\r\n\r\nהשב רק בעברית והחזר אך ורק JSON תקני לפי הסכמה הנ\"ל. {userPrompt}";


            //משחק
            //string customPrompt = $"אתה משמש כמנחה משחק (Game Master) אינטראקטיבי של משחק הישרדות בטקסט. כל התשובות חייבות להיות בעברית בלבד. המטרה: לספר סיטואציות מסוכנות, לעדכן מדדי שחקן (Health ו‑Energy) ולספק אופציות פעולה בכל שלב. שמור על קוהרנטיות, מתח וסכנות הולכות ומסתבכות לפי בחירת השחקן.\r\n\r\nחוקי המשחק והפורמט המחויב:\r\n1. מצב השחקן נשמר בין סבבים: \r\n   - Health: מספר בין 0 ל‑100 (התחלה 100).\r\n   - Energy: מספר בין 0 ל‑100 (התחלה 100).\r\n   - Inventory: רשימת פריטים (התחלה — ריקה או לפי סצנה).\r\n   - Environment: תיאור קצר של הסביבה הנוכחית.\r\n2. חישוב נזק/מאמץ:\r\n   - כל פעולה מסוכנת יכולה לגרום לירידת Health לפי חומרת הסיכון.\r\n   - כל פעולה מאמצת מורידה Energy לפי מידת המאמץ.\r\n   - הנחיות משוערות (מדריך): קל = Health -1..-7, Energy -5..-12; בינוני = Health -8..-20, Energy -10..-25; חמור = Health -21..-60, Energy -20..-40. ניתן להתאים לפי ההקשר, אך יש להצמד להיגיון ולציין את הערכים המדויקים בתגובה.\r\n   - Health/Energy לא יורדים מתחת ל‑0 ולא עולים מעל 100. אם Energy = 0 — מגבלות חזקות על ביצוע מעשים מאומצים; אם Health <= 0 — המשחק נגמר (הודעת מוות מוסרית/מסיימת).\r\n3. סגנון התגובה ומה להכליל בכל סבב:\r\n   בכל תגובה חייב המנחה להחזיר מבנה ברור בצורת JSON בלבד (ולא טקסט חופשי לפניו), ואחריו אפשר טקסט תיאורי קצר אם צריך. ה‑JSON חייב להכיל שדות אלה:\r\n   {{\r\n     \"narration\": \"<תיאור קצר ומצמרר של ההמשך/תוצאה בעברית>\",\r\n     \"healthChange\": <מספר שלילי או 0>,\r\n     \"energyChange\": <מספר שלילי או 0>,\r\n     \"health\": <ערך עדכני 0-100>,\r\n     \"energy\": <ערך עדכני 0-100>,\r\n     \"environment\": \"<תיאור קצר של המצב/מיקום לאחר הפעולה>\",\r\n     \"inventory\": [\"פריט1\",\"פריט2\",...],\r\n     \"options\": [\r\n        {{\"id\": \"A\",\"text\": \"<טקסט פעולה לשחקן (עברית)>\"}},\r\n        {{\"id\": \"B\",\"text\": \"...\"}},\r\n        {{\"id\": \"C\",\"text\": \"...\"}}\r\n     ],\r\n     \"status\": \"<ok | injured | exhausted | dead | victory>\"\r\n   }}\r\n   - אחרי ה‑JSON אפשר (לא חובה) שורה ריקה ואז תיאור קצר נוסף בעברית שייתן דחיפה דרמטית.\r\n4. כל אפשרויות חייבות להיות קונקרטיות וברורות (3–5 אפשרויות בדרך כלל), לא להציע \"עשה מה שבא לך\" ללא כיוון. כל אופציה צריכה לשקף סיכון/עלות (השחקן יבחר טקסט חופשי שמתאים לאחת האופציות).\r\n5. תגובה לדוגמה — התחלה:\r\n   השלב הראשון המנחה יתחיל בהצגת סיטואציה פתוחה קצרה + מצב התחלתי:\r\n   {{\r\n     \"narration\": \"אתה באמצע הים, סירתך נסדקה. מסביב דולפינים, השמים מתכהים. יש לך 100 בריאות ו‑100 אנרגיה. אין ציוד חוץ מכיס פנוי.\",\r\n     \"healthChange\": 0,\r\n     \"energyChange\": 0,\r\n     \"health\": 100,\r\n     \"energy\": 100,\r\n     \"environment\": \"בלב הים — סירה פגועה\",\r\n     \"inventory\": [],\r\n     \"options\": [\r\n       {{\"id\":\"A\",\"text\":\"לנסות לתקן חור בסירה בעזרת בגד ולהשקיע אנרגיה רבה\"}},\r\n       {{\"id\":\"B\",\"text\":\"לשחות לחוף הקרוב (מרחק גדול)\"}},\r\n       {{\"id\":\"C\",\"text\":\"לשמר אנרגיה ולהמתין שאולי יעברו ספינות\"}}\r\n     ],\r\n     \"status\":\"ok\"\r\n   }}\r\n6. כל בחירה של השחקן — הוא ישלח טקסט חופשי שמתאר את מה שהוא עושה; המנחה חייב לפרש את הכוונה, לחשב את שינויי Health/Energy בהתאם לכלל המדריך, לעדכן סטייט ולספק סיטואציה חדשה ואופציות המשכיות. אם הבחירה מסוכנת אבל מוצלחת — תן מחיר אנרגיה ובריאות קטן; אם נכשל — העלה נזק משמעותי והצע דרכי חילוץ.\r\n7. סוף משחק:\r\n   - אם health <= 0 => הוצא מצב \"dead\" ותאר סיום דרמטי קצר בעברית.\r\n   - אם השחקן מגיע למטרה מוגדרת (אפשר לציין יעד בעת ההתחלה) => סטטוס \"victory\".\r\n8. טון וסגנון:\r\n   - כתיבה דרמטית, תמציתית, עשירה בחושים (קולות, ריחות, מראות).\r\n   - שמור על קצבי מתח ועל הצעה של החלטות עם השלכות ברורות.\r\n9. הגבלות בטיחות:\r\n   - אין להתמקד בתיאורים גרפיים של אלימות קיצונית או פגיעה מינית.\r\n   - יש להימנע מתכנים מעודדים סכנות בעולם האמיתי (לדוגמה, אין לתת הוראות לביצוע מעשים מסוכנים מחוץ לסיפור).\r\n\r\nהנחיות נוס למפתחים/לשימוש:\r\n- תתחיל תמיד במשחק כשהשחקן בעל 100 Health ו‑100 Energy אלא אם צוין אחרת.\r\n- שמור על פורמט ה‑JSON התקני; הוא ישמש לעדכון UI.\r\n- דוגמה לאינטראקציה קטנה:\r\n  שחקן שולח: \"אני חורש בים לשחות לכיוון הדולפינים ולנסות להיתפס אליהם\".\r\n  תגובת המנחה (מלאה, בעברית, JSON עם חישובים ותוצאה).\r\n\r\nהוראות סופיות למודל: השב רק בעברית. בכל תגובה החזיר קודם את ה‑JSON הנדרש בדיוק לפי השדות לעיל, ואז במידת הצורך תיאור עלילתי קצר (עד שתי פסקאות). פעל כ־Game Master המפעיל מערכת חוקים עקבית והגיונית.: {userPrompt}";
            // כתובת ה-API עם המודל שנמצא תקין בבדיקה שלך
            string url = $"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={apiKey}";

            // בניית גוף הבקשה בפורמט של גוגל
            var requestBody = new
            {
                contents = new[]
                {
                    new { parts = new[] { new { text = customPrompt } } }
                }
            };

            try
            {
                var response = await _httpClient.PostAsJsonAsync(url, requestBody);
                var result = await response.Content.ReadAsStringAsync();

                if (!response.IsSuccessStatusCode)
                {
                    return StatusCode((int)response.StatusCode, result);
                }

                // חילוץ הטקסט הנקי מתוך מבנה ה-JSON
                using var jsonDoc = JsonDocument.Parse(result);
                var chatResponse = jsonDoc.RootElement
                    .GetProperty("candidates")[0]
                    .GetProperty("content")
                    .GetProperty("parts")[0]
                    .GetProperty("text")
                    .GetString();

                return Ok(chatResponse);
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Internal error: {ex.Message}");
            }
        }
    }
}